    59→                    .compoundSearchField()
    60→                    .disableAutocorrection(true)
    61→                }
    62→            }
    63→            .introspect(.scrollView, on: .supportedVersions) { scrollView in
    64→                guard scrollView != scrollViewAdapter.scrollView else { return }
    65→                scrollViewAdapter.scrollView = scrollView
    66→            }
    67→            .onReceive(scrollViewAdapter.didScroll) { _ in
    68→                updateVisibleRange()
    69→            }
    70→            .onReceive(scrollViewAdapter.isScrolling) { _ in
    71→                updateVisibleRange()
    72→            }
    73→            .onChange(of: context.searchQuery) {
    74→                updateVisibleRange()
    75→            }
    76→            .onChange(of: context.viewState.visibleRooms) {
