    79→                // We have been seeing a lot of issues around the room list not updating properly after
    80→                // rooms shifting around:
    81→                // * Tapping on the room list doesn't always take you to the right room  - https://github.com/element-hq/element-x-ios/issues/2386
    82→                // * Big blank gaps in the room list - https://github.com/element-hq/element-x-ios/issues/3026
    83→                //
    84→                // We initially thought it's caused by the filters header or the geometry reader but
    85→                // the problem is still reproducible without those.
    86→                //
    87→                // As a last attempt we will manually force it to update by shifting the
    88→                // inner scroll view by a point every time the room list is updated
    89→                DispatchQueue.main.async {
    90→                    guard !scrollViewAdapter.isScrolling.value, let scrollView = scrollViewAdapter.scrollView else {
    91→                        return
    92→                    }
    93→                    
    94→                    let oldOffset = scrollView.contentOffset
    95→                    var newOffset = scrollView.contentOffset
    96→                    newOffset.y += 1
    97→                    
    98→                    scrollView.setContentOffset(newOffset, animated: false)
    99→                    scrollView.setContentOffset(oldOffset, animated: false)
   100→                }
