   123→    @ViewBuilder
   124→    private var topSection: some View {
   125→        // An empty VStack causes glitches within the room list
   126→        if context.viewState.shouldShowFilters || context.viewState.shouldShowBanner {
   127→            VStack(spacing: 0) {
   128→                if context.viewState.shouldShowFilters {
