   142→    /// Often times the scroll view's content size isn't correct yet when this method is called e.g. when cancelling a search
   143→    /// Dispatch it with a delay to allow the UI to update and the computations to be correct
   144→    /// Once we move to iOS 17 we should remove all of this and use scroll anchors instead
   145→    private func updateVisibleRange() {
   146→        DispatchQueue.main.asyncAfter(deadline: .now() + 0.5) { delayedUpdateVisibleRange() }
   147→    }
   148→    
   149→    private func delayedUpdateVisibleRange() {
   150→        guard let scrollView = scrollViewAdapter.scrollView,
   151→              scrollViewAdapter.isScrolling.value == false, // Ignore while scrolling
   152→              context.searchQuery.isEmpty == true, // Ignore while filtering
   153→              context.viewState.visibleRooms.count > 0 else {
   154→            return
   155→        }
   156→        
   157→        guard scrollView.contentSize.height > scrollView.bounds.height else {
   158→            return
   159→        }
   160→        
   161→        let adjustedContentSize = max(scrollView.contentSize.height - scrollView.contentInset.top - scrollView.contentInset.bottom, scrollView.bounds.height)
   162→        let cellHeight = adjustedContentSize / Double(context.viewState.visibleRooms.count)
   163→        
   164→        let firstIndex = Int(max(0.0, scrollView.contentOffset.y + scrollView.contentInset.top) / cellHeight)
   165→        let lastIndex = Int(max(0.0, scrollView.contentOffset.y + scrollView.bounds.height) / cellHeight)
   166→        
   167→        // This will be deduped and throttled on the view model layer
   168→        context.send(viewAction: .updateVisibleItemRange(firstIndex..<lastIndex))
   169→    }
   170→}
